# (чтение) после отражения ТД 3/4: проводки и сальдо 3132.5, 3232, 3310 Geze
for r in q('ВЫБРАТЬ Д.Ссылка КАК Р ИЗ Документ.ТаможеннаяДекларацияИмпорт КАК Д ГДЕ Д.Дата >= &Н И Д.Номер В ("00НФ-000003","00НФ-000004")', Н=datetime.datetime(2026, 1, 1)):
    print('==', s(r['Р'])[:55])
    for x in q('ВЫБРАТЬ Х.СчетДт.Код КАК Дт, Х.СчетКт.Код КАК Кт, СУММА(Х.Сумма) КАК С ИЗ РегистрБухгалтерии.{REG} КАК Х ГДЕ Х.Регистратор = &Р СГРУППИРОВАТЬ ПО Х.СчетДт.Код, Х.СчетКт.Код', Р=r['Р']):
        print('   БУ', x['Дт'], x['Кт'], f"{float(x['С']):,.2f}")
for r in q('ВЫБРАТЬ Т.Счет.Код КАК С, Т.Субконто1 КАК К, СУММА(Т.СуммаОстатокДт - Т.СуммаОстатокКт) КАК Б ИЗ РегистрБухгалтерии.{REG}.Остатки(&Н, Счет.Код В ("3132.5","3232","3310"), , Организация.Наименование ПОДОБНО "%ANESCOM%") КАК Т СГРУППИРОВАТЬ ПО Т.Счет.Код, Т.Субконто1', Н=datetime.datetime(2026, 10, 27)):
    if r['С'] != '3310' or 'Geze' in s(r['К']) or 'GEZE' in s(r['К']).upper():
        print('  ', r['С'], s(r['К'])[:35], f"{float(r['Б'] or 0):,.2f}")
